traps.trap01.txt:
// 切换到map097湖口村茶馆

	If ($Event == 610) @Event610;
	
	Say("独孤剑：现在怎能回去？", 1);
	Return;
	
@Event610:	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map097_湖口村茶馆.map");
	LoadObj("map097.obj"); 
	AddObj("茶馆掌柜尸体.ini", 8, 14, 2);
	AddObj("茶馆留书.ini", 4, 17, 0);
	SetObjScript("茶馆留书", "桌上的书信.txt");
	SetPlayerPos(6, 9);
	SetPlayerDir(0);
	SetNpcKind("杨瑛", 1);
	SetNpcPos("杨瑛", 7, 10);
	SetNpcDir("杨瑛", 0);
	FadeIn();
	NpcGoto("杨瑛", 7, 12);
	Say("杨瑛：啊！龚楷……", 42);
	PlayerGoto(5, 10);
	SetPlayerDir(1);
	Say("独孤剑：琳心！琳心！", 6);
	NpcGoto("杨瑛", 5, 11);
	Watch("独孤剑", "杨瑛", 0);
	Say("杨瑛：龚楷被人杀了，一定是封玉书干的，杀人灭口！龚楷被杀，我们就不知道封玉书向何处走了。", 42);
	Say("独孤剑：我的两位朋友也不见了！", 9);
	Say("杨瑛：别着急，说不定他们临走时留下了什么线索，我们四处找找。", 39);
	SetNpcKind("杨瑛", 3);
	SetNpcRelation("杨瑛", 2);
	SetNpcScript("杨瑛", "杨瑛的同伴对话.txt");
	Return;

